using UnityEngine;
namespace Rekindle {
 public sealed class WorldInteractable:MonoBehaviour {
  [SerializeField]string stableId,title,detail,item;[SerializeField]int quantity=3;[SerializeField]InteractionKind kind;[SerializeField]GameObject ruined,stabilized,restored;Session session;
  public string Id=>stableId;public string Title=>title;public InteractionKind Kind=>kind;public string Detail=>detail;
  public void Configure(string id,string name,InteractionKind type,string description="",string resource="",int amount=3){stableId=id;title=name;kind=type;detail=description;item=resource;quantity=amount;}
  public void Visuals(GameObject a,GameObject b,GameObject c){ruined=a;stabilized=b;restored=c;}
  public void Bind(Session s){session=s;session.World.Changed+=Refresh;Refresh();}void OnDestroy(){if(session)session.World.Changed-=Refresh;}
  public void Refresh(){if(kind==InteractionKind.Building){int stage=session.World.Stage(stableId);if(ruined)ruined.SetActive(stage==0);if(stabilized)stabilized.SetActive(stage==1);if(restored)restored.SetActive(stage==2);}if(kind==InteractionKind.Resource)gameObject.SetActive(!session.World.IsDepleted(stableId));if(kind==InteractionKind.ReturnGate)gameObject.SetActive(session.World.BossDefeated);}
  public void Interact(){if(!session.Player.Alive){session.Notify("Your ember is returning to the hearth.");return;}if(kind==InteractionKind.Resource&&session.World.IsDepleted(stableId)){session.Notify("Already gathered");return;}if(Vector3.Distance(transform.position,session.Player.transform.position)>5){session.Notify("Move closer to "+title);return;}switch(kind){case InteractionKind.Resource:if(session.Bag.Add(item,quantity)){session.World.Deplete(stableId);session.Notify("+"+quantity+" "+session.ItemTitle(item));Feedback.Burst(transform.position+Vector3.up,new Color(1,.75f,.3f),12);session.Save();}else session.Notify("Inventory full : make room first");break;case InteractionKind.Building:session.Inspect(this);break;case InteractionKind.Soul:string words;if(stableId=="soul-hearth")words=session.World.Stage("hearth")<2?"Elian: The Soul Dragon broke our bodies, but our memories remain. I remember a fire... a roof. Restore my house with wood and stone.":"Elian: I have a name again. Thank you. Mira waits by the forge; her old duty may bring her home too.";else if(stableId=="soul-forge")words=session.World.Stage("forge")==0?"Mira: I shaped iron here. Stone and bog iron could steady the forge, but a part of me is still lost.":session.World.Stage("forge")==1?"Mira: My forge remembers me. My personal hammer lies in the sanctuary beyond the eastern woods. The Ash Warden holds it.":"Mira: You brought back more than my hammer. My forge is yours, and the Dawn Beacon can burn again.";else words=session.World.Stage("garden")<2?"Sera: I remember planting for everyone. Return wood and wildfruit to our garden; let the valley grow again.":"Sera: These green things remember us. The first harvest is ready for you at the garden.";session.Notify(words,10);break;case InteractionKind.ReturnGate:session.Motor.Teleport(new Vector3(0,2,-5));session.Notify("The cleansed waystone carries you home");break;case InteractionKind.Anchor:session.Notify("The Ash Warden guards the last ember. Defeat it to recover the anchors.");break;}}
 }
}
